feed:
  {{ site.author }}


  {{ site.url }}/
  {{ site.author }}
  {{ updated|iso }}
  {% for item in items %}

    {{ item.heading }}

    {{ site.url }}{{ item.url }}
    {{ item.date|iso }}
    {{ (item.updated or item.date)|iso }}

    {% if item.excerpt %}{{ item.excerpt }}{% endif %}
    {% if item.kind == "photo" %}
    {% set body %}{{ picture(item.image, alt=item.caption) }}{% if item.caption %}
{{ item.caption }}{% endif %}{% endset %}
    {{ body|absolute }}
    {% else %}
    {{ item.html|absolute }}
    {% endif %}

  {% endfor %}
